const id = () => crypto.randomUUID();
const hash = (password, salt = crypto.randomBytes(16).toString('hex')) => ({ salt, digest: crypto.scryptSync(password, salt, 64).toString('hex') });
function audit(actor, action, entity, entityId) { db.prepare('INSERT INTO audit_logs(id,actor_id,action,entity,entity_id) VALUES(?,?,?,?,?)').run(id(), actor || null, action, entity, entityId || null); }
function notify(userId, title, body, href) { if (userId) db.prepare('INSERT INTO notifications(id,user_id,title,body,href) VALUES(?,?,?,?,?)').run(id(), userId, title, body, href || null); }
function notifyAnnouncement(a){let audience=[];try{audience=JSON.parse(a.roles||'[]')}catch{}for(const recipient of db.prepare("SELECT id,role,jurisdiction FROM users WHERE status='active'").all())if((!audience.length||audience.includes(recipient.role))&&rowScope(recipient,a.jurisdiction))notify(recipient.id,'New announcement',a.title,'/announcements');}
function processAnnouncementSchedules(){const expired=db.prepare("SELECT id FROM announcements WHERE status='Published' AND expires_at IS NOT NULL AND datetime(expires_at)<=CURRENT_TIMESTAMP").all();for(const item of expired){db.prepare("UPDATE announcements SET status='Unpublished' WHERE id=?").run(item.id);audit(null,'expire','announcement',item.id);}const due=db.prepare("SELECT * FROM announcements WHERE status='Scheduled' AND scheduled_at IS NOT NULL AND datetime(scheduled_at)<=CURRENT_TIMESTAMP AND (expires_at IS NULL OR datetime(expires_at)>CURRENT_TIMESTAMP)").all();for(const item of due){db.prepare("UPDATE announcements SET status='Published' WHERE id=?").run(item.id);notifyAnnouncement(item);audit(null,'publish_scheduled','announcement',item.id);}const missed=db.prepare("SELECT id FROM announcements WHERE status='Scheduled' AND expires_at IS NOT NULL AND datetime(expires_at)<=CURRENT_TIMESTAMP").all();for(const item of missed){db.prepare("UPDATE announcements SET status='Unpublished' WHERE id=?").run(item.id);audit(null,'expire','announcement',item.id);}}
function processTaskDeadlineReminders(){const today=new Date().toISOString().slice(0,10),tomorrow=new Date(Date.now()+86_400_000).toISOString().slice(0,10),rows=db.prepare("SELECT * FROM tasks WHERE assigned_to IS NOT NULL AND due_date GLOB '????-??-??' AND status NOT IN ('Submitted','Completed','Cancelled') AND due_date<=?").all(tomorrow);for(const task of rows){const overdue=task.due_date<today,type=overdue?'overdue':'due_soon',reminderDate=overdue?today:task.due_date,insert=db.prepare('INSERT OR IGNORE INTO task_deadline_reminders(id,task_id,reminder_type,reminder_date) VALUES(?,?,?,?)').run(id(),task.id,type,reminderDate);if(!insert.changes)continue;const title=overdue?'Task overdue':'Task due soon',body=overdue?`${task.title} was due ${task.due_date}.`:`${task.title} is due ${task.due_date}.`;for(const recipientId of new Set([task.assigned_to,task.created_by]))if(db.prepare("SELECT id FROM users WHERE id=? AND status='active'").get(recipientId))notify(recipientId,title,body,'/tasks');}}
setInterval(processAnnouncementSchedules,15_000).unref();
setInterval(processTaskDeadlineReminders,60_000).unref();
function bootstrap() {
  if (db.prepare('SELECT count(*) n FROM users').get().n) return;
  const password = process.env.BOOTSTRAP_ADMIN_PASSWORD;
  if (!password) return;
  const h = hash(password);
  db.prepare('INSERT INTO users(id,username,full_name,role,status,password_hash,salt) VALUES(?,?,?,?,?,?,?)').run(id(), process.env.BOOTSTRAP_ADMIN_USERNAME || 'admin', process.env.BOOTSTRAP_ADMIN_NAME || 'Super Administrator', roles[0], 'active', h.digest, h.salt);
}
bootstrap();
processTaskDeadlineReminders();

const sessions = new Map();
const loginAttempts = new Map();
const json = (res, status, data, headers = {}) => { res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...headers }); res.end(JSON.stringify(data)); };
function readBody(req, maxBytes = 1_000_000) { return new Promise((resolve, reject) => { let body = '', failed = false; req.on('data', x => { if (failed) return; body += x; if (body.length > maxBytes) { failed = true; reject(new Error('Request too large')); } }); req.on('end', () => { if (failed) return; try { resolve(body ? JSON.parse(body) : {}); } catch { reject(new Error('Invalid JSON')); } }); req.on('error', reject); }); }
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"'&&cell==='')quoted=true;else if(c===','){row.push(cell);cell='';}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV contains an unfinished quoted field.');if(cell.length||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}return rows;}
function csvCell(value){let text=String(value??'');if(/^[\s]*[=+@\-\t\r]/.test(text))text="'"+text;return `"${text.replaceAll('"','""')}"`;}
function contactDuplicateKeys(row){const email=String(row.email||'').trim().toLowerCase(),phone=String(row.phone||'').replace(/\D/g,''),whatsapp=String(row.whatsapp||'').replace(/\D/g,'');return[email&&`e:${email}`,phone.length>=7&&`p:${phone}`,whatsapp.length>=7&&`p:${whatsapp}`].filter(Boolean);}
function cookieToken(req) { const raw = req.headers.cookie || ''; return raw.split(';').map(x => x.trim()).find(x => x.startsWith('sid='))?.slice(4); }
function auth(req, res) {
  const token = cookieToken(req), session = token && sessions.get(token);
  if (!session || session.expires < Date.now()) { if (token) sessions.delete(token); json(res, 401, { error: 'Please sign in again.' }); return null; }
  const user = db.prepare('SELECT id,username,full_name,role,status,jurisdiction,email,phone,must_change_password FROM users WHERE id=?').get(session.userId);
  if (!user || user.status !== 'active') { sessions.delete(token); json(res, 401, { error: 'Account is inactive.' }); return null; }
  return user;
}
const admin = (u, res) => { if (u.role !== roles[0]) { json(res, 403, { error: 'Administrator access required.' }); return false; } return true; };
const scope = (u, alias = '') => u.role === roles[0] ? '' : ` AND ${alias}jurisdiction = ?`;
function rowScope(u, jurisdiction) {
  if (u.role === roles[0] || !jurisdiction) return true;
  if (!u.jurisdiction) return false;
  if (jurisdiction === u.jurisdiction) return true;
  if (u.role === 'Mandal-Level In-Charge') return Boolean(db.prepare("SELECT 1 FROM organization_units v JOIN organization_units m ON v.parent_id=m.id WHERE v.unit_type='Village' AND v.status='active' AND m.unit_type='Mandal' AND m.status='active' AND v.name=? AND m.name=?").get(jurisdiction, u.jurisdiction));
  return false;
}
function canReadDocument(doc, user) { if (user.role === roles[0]) return true; let audience; try { audience = JSON.parse(doc.audience_roles || '[]'); } catch { return false; } return !doc.archived && (!audience.length || audience.includes(user.role)) && rowScope(user, doc.jurisdiction); }
