const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');if(url.pathname.startsWith('/api/'))return await routes(req,res,url.pathname);let filename=url.pathname==='/'?'index.html':path.basename(url.pathname);let target=path.join(root,'public',filename);if(!target.startsWith(path.join(root,'public')))return json(res,404,{error:'Not found.'});try{const data=fs.readFileSync(target);res.writeHead(200,{'Content-Type':filename.endsWith('.css')?'text/css; charset=utf-8':filename.endsWith('.js')?'text/javascript; charset=utf-8':filename.endsWith('.webmanifest')?'application/manifest+json; charset=utf-8':filename.endsWith('.svg')?'image/svg+xml': 'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'same-origin','Content-Security-Policy':"default-src 'self'; style-src 'self'; script-src 'self'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'"});res.end(data);}catch{json(res,404,{error:'Not found.'});}}catch(e){console.error(e);json(res,500,{error:'The request could not be completed.'});}});
const port=Number(process.env.PORT||3000);
const host=process.env.HOST||(process.env.NODE_ENV==='production'?'0.0.0.0':'127.0.0.1');
server.listen(port,host,()=>console.log(`YSRCP Narasaraopet listening on http://${host}:${port}`));
